# Generate 100,000 stellar masses
stellar_masses = sample_kroupa_imf(size=100000)

# Define the Kroupa IMF as a function
def kroupa_imf(m):
    """Evaluate the Kroupa IMF at the mass m."""
    if m < 0.01:
        return 0
    elif m < 0.08:
        return K1 * m**(-0.3)
    elif m < 0.5:
        return K2 * m**(-1.3)
    elif m <= 1.0:
        return K3 * m**(-2.3)
    else:
        return 0

# Statistics of the stellar population (the mean of a mask is the fraction of True values)
print(f"Mean mass = {np.mean(stellar_masses):.4f} M☉, median mass = {np.median(stellar_masses):.4f} M☉")
print(f"Fraction of stars above 0.5 M☉ = {np.mean(stellar_masses > 0.5):.4f}")
